function renderDocuments(data,pane){renderDocumentWorkspace(data,pane);if(!staff()&&data.requirements.some(r=>!r.waived&&r.applicable&&!['file','heading','paragraph','divider'].includes(r.definition.type))){const section=document.createElement('section');section.className='client-information-fields';const workspace=pane.querySelector('.document-workspace');if(workspace)workspace.before(section);else pane.append(section);renderInformation(data,section,true);}}
function renderDocumentWorkspace(data,pane){const {file,requirements,documents}=data,rows=requirements.filter(r=>r.definition.type==='file'&&!r.waived&&r.applicable);if(!rows.length){pane.innerHTML=categoryGuidance(data.categoryInstructions||[],!staff())+empty('No documents requested',staff()?'Check the Information tab for the fields that apply to this file.':'Complete any application details requested below.');return;}const chosen=rows.find(r=>String(r.id)===String(selectedDocument)) || (!staff()?clientDocumentState(data).next:null) || rows.find(r=>documents.find(v=>v.requirement_id===r.id)?.status==='PENDING') || rows[0];selectedDocument=chosen.id;const versions=documents.filter(v=>v.requirement_id===chosen.id),latest=versions[0],d=chosen.definition,editable=!['SUBMITTED','COMPLETED','CANCELLED'].includes(file.status);pane.innerHTML=categoryGuidance(data.categoryInstructions ?? requirements.filter(r=>!r.waived&&r.applicable).map(r=>r.definition),!staff())+categoryLayout(requirements.filter(r=>!r.waived&&r.applicable&&!r.definition.instructionRole&&['heading','paragraph','divider'].includes(r.definition.type)).map(r=>r.definition))+`<div class="document-workspace"><section class="document-list"><div class="section-heading"><h2>Document checklist</h2><span>${rows.length} ${rows.length===1?'document':'documents'}</span></div>${rows.map((r,index)=>{const v=documents.find(v=>v.requirement_id===r.id);const group=r.definition.section||'Documents';const heading=index===0||group!==(rows[index-1].definition.section||'Documents')?`<h3 class="document-group">${esc(group)}</h3>`:'';return heading+`<button class="document-item ${r.id===chosen.id?'selected':''}" data-document="${r.id}"><span class="file-icon">▤</span><span><strong>${esc(r.definition.label)}</strong><small>${r.definition.required?'Required':'Optional'}</small>${v?documentBadge(v.status):'<span class="badge missing">Upload needed</span>'}</span><i>›</i></button>`;}).join('')}</section><section class="document-detail"><div class="section-heading"><div><h2>${esc(d.label)}</h2><p>${d.required?'Required document':'Optional document'}</p></div>${latest?documentBadge(latest.status):'<span class="badge missing">Upload needed</span>'}</div><div class="guide"><span>ⓘ</span><div><strong>What to upload</strong><div class="formatted-guide">${guideMarkup(d.guide || 'Upload a clear, readable copy of the requested document.')}</div><small>${d.formats.join(', ').toUpperCase()} · Maximum ${d.maxMB} MB</small>${d.sampleUrl?`<p><a href="${esc(d.sampleUrl)}" target="_blank" rel="noopener">View an example →</a></p>`:''}</div></div>${latest?.status==='REJECTED'?`<div class="document-correction"><span class="correction-icon" aria-hidden="true">!</span><div><span class="correction-eyebrow">OPERATIONS FEEDBACK</span><strong>Changes requested</strong><p>${esc(latest.reason)}</p>${editable?'<small>Upload a revised document below to continue.</small>':''}</div></div>`:''}${latest&&latest.status!=='REMOVED'?`${documentPreview(latest)}${documentFileToolbar(latest,editable)}`:empty('Your document goes here','Choose a file below to get started.')}${staff()&&editable&&latest?.status==='PENDING'?`<div class="review-actions"><button id="reject-document">Request correction</button><button class="primary" id="accept-document">✓ Accept document</button></div>`:''}${editable&&(staff()||latest?.status!=='ACCEPTED')?clientUploadPanel(form('upload-document',`<div class="upload-zone" id="document-dropzone"><span class="upload-icon" aria-hidden="true">↑</span><div class="upload-copy"><strong>${latest?'Replace this document':'Upload your document'}</strong><p>Drag and drop your file here, or browse to choose one.</p><small>${d.formats.join(', ').toUpperCase()} · Maximum ${d.maxMB} MB</small></div><label class="browse-document" for="document-file-picker">Browse files</label><input id="document-file-picker" name="file" type="file" aria-label="Choose document" accept="${d.formats.map(f=>'.'+f).join(',')}" required><div id="upload-selection" role="status" aria-live="polite">No file selected</div></div>`,latest?'Upload new version':'Upload document'),latest):''}${versions.length?`<details class="history"><summary>Submission history (${versions.length})</summary>${versions.map(v=>`<div class="history-row"><span>Version ${v.version}<small>${date(v.reviewed_at || v.created_at)}</small></span>${documentBadge(v.status)}${v.status!=='REMOVED'?`<a href="/api/documents/${v.id}/file">Download</a>`:'<span class="muted">File removed</span>'}${v.reason?'<p>'+esc(v.reason)+'</p>':''}</div>`).join('')}</details>`:''}</section></div>`;pane.querySelectorAll('[data-preview-toggle]').forEach(details=>details.addEventListener('toggle',()=>{if(details.open){const frame=details.querySelector('iframe');if(!frame.src)frame.src=frame.dataset.previewSrc;}}));action('[data-document]',async b=>{selectedDocument=b.dataset.document;await render();});const picker=pane.querySelector('#upload-document input[type=file]');if(picker){const zone=pane.querySelector('#document-dropzone'),submit=pane.querySelector('#upload-document button.primary');submit.disabled=true;const selectFile=()=>{const selected=picker.files[0];submit.disabled=!selected;zone.classList.toggle('has-file',!!selected);pane.querySelector('#upload-selection').textContent=selected?selected.name+' · '+(selected.size/1024/1024).toFixed(2)+' MB':'No file selected';};picker.addEventListener('change',selectFile);zone.addEventListener('dragover',e=>{e.preventDefault();zone.classList.add('drag-over');});zone.addEventListener('dragleave',()=>zone.classList.remove('drag-over'));zone.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('drag-over');if(e.dataTransfer.files.length!==1){success('Choose one document at a time.');return;}picker.files=e.dataTransfer.files;selectFile();});}action('#verify-document-storage',async()=>{const result=await api('documents/'+latest.id+'/storage');modal('Document storage',`<div class="storage-proof"><strong>${result.verified?'Verified in GoHighLevel Media':'Legacy server storage'}</strong><p>${esc(result.message)}</p>${result.mediaId?'<p>GHL Media ID: <code>'+esc(result.mediaId)+'</code></p>':''}<p class="hint">Download links use the Operations address to check access. The address does not indicate where the document is stored.</p></div>`);});action('#remove-document',async()=>{modal('Remove document',`<p>Remove ${esc(latest.original_name)} from storage? Its history will remain and a replacement can be uploaded.</p>`+form('remove-document-form',area('Reason for removal','reason'),'Remove file'));bindForm('remove-document-form',async v=>{await api('documents/'+latest.id,'DELETE',v);closeModal();await render();success('File removed. You can upload a replacement.');});});bindForm('upload-document',async(v,f)=>{const result=await api(`cases/${file.id}/requirements/${chosen.id}/upload`,'POST',new FormData(f));await render();success(result.storageProvider==='GHL'?'Document stored in GoHighLevel Media and awaiting review.':'Document uploaded and awaiting review.');});action('#accept-document',async()=>{await api('documents/'+latest.id+'/review','POST',{status:'ACCEPTED'});await render();success(data.file.client_notifications_enabled===0?'Document accepted. Client notifications are stopped.':'Document accepted. Client notification queued.');});action('#reject-document',async()=>{modal('Request a corrected document',`<p>Explain what ${esc(file.client_name)} needs to change.</p>`+form('reject-form',area('Reason for correction','reason'),'Send correction request'));bindForm('reject-form',async v=>{await api('documents/'+latest.id+'/review','POST',{status:'REJECTED',reason:v.reason});closeModal();await render();success('Correction requested. The client can upload a new version.');});});}
function renderInformation(data,pane,inputsOnly=false){const {file,requirements}=data,rows=requirements.filter(r=>r.definition.type!=='file'&&!r.waived&&r.applicable&&(!inputsOnly||!['heading','paragraph','divider'].includes(r.definition.type))),fields=rows.map(r=>({...r.definition,controlName:String(r.id)})),values=Object.fromEntries(rows.map(r=>[String(r.id),r.value_json]));pane.innerHTML=card(staff()?'Client information':'Application details','<p class="muted">Follow the guidance below. You can save your progress and return later.</p>'+form('case-values',categoryLayout(fields,values),'Save details'))+(staff()?card('Completed Client Summary',summary(file.summary_json)):'');installFieldReviews(data,pane,rows);if(['SUBMITTED','COMPLETED','CANCELLED'].includes(file.status)||clientPreview)pane.querySelectorAll('form input,form select,form textarea,form button').forEach(e=>e.disabled=true);bindForm('case-values',async(v,f)=>{const saved={};for(const r of rows){const d=r.definition;if(['heading','paragraph','divider'].includes(d.type))continue;saved[r.id]=d.type==='checkbox'?f.elements.namedItem(String(r.id)).checked:d.type==='number'?v[r.id]===''?null:Number(v[r.id]):v[r.id] ?? '';}await api('cases/'+file.id+'/values','PUT',{values:saved});await render();success('Your details have been saved.');});}

function timeline(rows){return renderActivityTimeline(rows);}
async function moreActions(data){const {file}=data;modal('File actions',`<div class="action-menu"><button id="add-request">＋ Request an extra document or field</button><button id="add-note">≡ Add an internal note</button>${manager()?'<button id="edit-assignment">♙ Change file owner or deadline</button><button id="waive-item">✓ Waive a requirement</button><button id="migrate-checklist">▦ Change category / checklist</button><button id="reopen-file">↻ Reopen document collection</button><button id="cancel-file">× Cancel file</button>':''}</div>`);action('#add-request',async()=>{modal('Request an additional item',form('extra',input('What do you need?','label','text','','required')+select('Type','type',[['file','Document upload'],['text','Text'],['date','Date'],['email','Email'],['number','Number'],['textarea','Long answer']])+area('Instructions for the client','guide')+check('Required to complete this file','required',true)+area('Why is this needed?','reason'),'Send request'));bindForm('extra',async(v,f)=>{await api('cases/'+file.id+'/requirements','POST',{field:{label:v.label,type:v.type,guide:v.guide,required:f.elements.required.checked},reason:v.reason});closeModal();await render();success('Additional item requested.');});});action('#add-note',async()=>{modal('Internal note',form('note',area('Only your team can see this note','message'),'Save note'));bindForm('note',async v=>{await api('cases/'+file.id+'/notes','POST',v);closeModal();success('Internal note saved.');});});action('#edit-assignment',async()=>{const agents=await api('staff');modal('File owner & deadline',form('assignment',select('File owner','assignedTo',agents.map(a=>[a.id,a.name]),file.assigned_to)+input('Deadline','dueAt','datetime-local'),'Save changes'));bindForm('assignment',async v=>{await api('cases/'+file.id+'/assignment','PATCH',{assignedTo:Number(v.assignedTo),dueAt:v.dueAt});closeModal();await render();});});action('#reopen-file',async()=>{modal('Reopen collection',form('reopen',area('Reason','reason'),'Reopen file'));bindForm('reopen',async v=>{await api('cases/'+file.id+'/status','POST',{status:'COLLECTING',reason:v.reason});closeModal();await render();});});action('#waive-item',async()=>{modal('Waive a requirement',form('waiver',select('Requirement','requirementId',data.requirements.filter(r=>!r.waived).map(r=>[r.id,r.definition.label]))+area('Reason for waiver','reason'),'Waive requirement'));bindForm('waiver',async v=>{await api(`cases/${file.id}/requirements/${v.requirementId}/waive`,'POST',{reason:v.reason});closeModal();await render();success('Requirement waived.');});});action('#migrate-checklist',async()=>{const cats=await api('categories');modal('Change the category checklist',form('migrate-checklist-form',select('Published category','categoryId',cats.filter(c=>c.status==='PUBLISHED').map(c=>[c.id,c.name]))+'<p class="hint">The old checklist and its document history will be retained. The new checklist will be requested.</p>'+check('Apply this new checklist to the client file','confirm',false),'Apply checklist'));bindForm('migrate-checklist-form',async(v,f)=>{await api('cases/'+file.id+'/category','POST',{categoryId:Number(v.categoryId),confirm:f.elements.confirm.checked});closeModal();selectedDocument=null;await render();});});action('#cancel-file',async()=>{modal('Cancel file',form('cancel-file-form',area('Reason for cancellation','reason'),'Cancel file'));bindForm('cancel-file-form',async v=>{await api('cases/'+file.id+'/status','POST',{status:'CANCELLED',reason:v.reason});closeModal();await render();});});}
function messageThread(rows,source='portal'){if(!rows.length)return '<div class="chat-empty"><span>◌</span><strong>No messages yet</strong><p>Your conversation will appear here in order.</p></div>';return `<div class="chat-thread">${[...rows].sort((a,b)=>(new Date(a.created_at || a.dateAdded)-new Date(b.created_at || b.dateAdded)) || (typeof a.id==='number'&&typeof b.id==='number'?a.id-b.id:0)).map(m=>{const own=source==='portal'?Number(m.actor_id)===Number(clientPreview?.clientUserId || user.id):m.direction==='outbound';let text=m.description || m.body || '';if(source==='portal'&&m.actor_name&&text.startsWith(m.actor_name+': '))text=text.slice(m.actor_name.length+2);if(source==='crm'){const decoder=document.createElement('textarea');decoder.innerHTML=text.replace(/<[^>]*>/g,' ');text=decoder.value;}return `<article class="chat-message ${own?'outgoing':'incoming'}"><div class="chat-author">${esc(source==='portal'?(m.actor_name || 'Operations'):(own?'Team · CRM':'Client · CRM'))}</div>${source==='crm'&&m.messageType?'<small>'+esc(m.messageType)+'</small>':''}<p>${esc(text || (source==='crm'?'Message has no text content.':''))}</p>${source==='crm'&&Array.isArray(m.attachments)?m.attachments.map((a,i)=>safeSourceLink(typeof a==='string'?a:a.url,'Attachment '+(i+1))).join(' '):''}<time>${esc(connectionTime(m.created_at || m.dateAdded))}</time></article>`;}).join('')}</div>`;}
function renderMessages(data,pane){const {file}=data;pane.innerHTML=`<p class="chat-channel">CLIENT PORTAL <span>Messages saved to this file</span></p>${messageThread(data.events.filter(e=>e.action==='PORTAL_MESSAGE'))}${form('portal-message',area('Your message','message'),'Send message')}`+(staff()?'<button class="email-history-link" id="open-email-history">View emails & delivery queue ('+data.emails.length+')</button>':'');action('#open-email-history',async()=>{conversationTab='emails';renderConversationPanel(data,document.querySelector('#conversation-panel'));});const thread=pane.querySelector('.chat-thread');if(thread)thread.scrollTop=thread.scrollHeight;bindForm('portal-message',async v=>{await api('cases/'+file.id+'/messages','POST',v);await render();success('Message sent.');});bindForm('compose-email',async v=>{await api('cases/'+file.id+'/email','POST',v);await render();success('Email queued for delivery.');});action('[data-retry]',async b=>{const uncertain=b.dataset.unknown==='true';if(uncertain&&!confirm('Have you checked your email provider and confirmed this email was not delivered?'))return;await api('emails/'+b.dataset.retry+'/retry','POST',{checkedCrm:uncertain});await render();success('Email retry queued.');});}

function taskRows(rows){return rows.length?rows.map(t=>`<div class="task-row ${taskUrgency(t)==='overdue'?'task-overdue':''}"><button data-task="${t.id}" data-status="DONE" aria-label="Complete task">○</button><div><strong>${esc(t.title)}</strong><small>${esc(t.client_name || t.assignee_name || '')} · ${taskDueLabel(t)}</small></div>${taskUrgency(t)==='overdue'?'<span class="badge rejected">Overdue — action needed</span>':badge('OPEN')}</div>`).join(''):empty('No outstanding tasks','Completed tasks are removed after completion.');}
