async function tasks(){content.innerHTML=card('Your task list',taskRows(await api('tasks')));bindTasks();}
function renderTasks(data,pane){pane.innerHTML=card('File tasks','<button id="new-task" class="primary">＋ Add task</button>'+taskRows(data.tasks));bindTasks();action('#new-task',async()=>{modal('Add a task',form('new-task-form',input('Task name','title','text','','required')+input('Due date','dueAt','datetime-local'),'Create task'));bindForm('new-task-form',async v=>{await api('cases/'+data.file.id+'/tasks','POST',v);closeModal();await render();});});}
async function notifications(){const rows=await api('notifications');content.innerHTML=card('Notifications · last 30 days',rows.length?rows.map(n=>`<div class="notification-row ${!n.read_at?'notification-unread':''}"><div><strong>${esc(n.description)}</strong><small>${date(n.created_at)} · ${n.read_at?'Read':'Unread'}</small></div>${n.case_id?`<button data-notification-open="${n.id}" data-case-id="${n.case_id}" data-target-tab="${/^(field-review:|field-result:)/.test(n.event_key)?'information':/^(task:|overdue-task:)/.test(n.event_key)?'tasks':/^(uploaded:|document-review:|review:|document-reminder:)/.test(n.event_key)?'documents':'overview'}">Open file →</button>`:''}${!n.read_at?`<button data-read="${n.id}">Mark read</button>`:''}</div>`).join(''):empty('You are up to date','Notifications from the last 30 days appear here.'));action('[data-notification-open]',async b=>{await api('notifications/'+b.dataset.notificationOpen+'/read','POST');selectedCase=b.dataset.caseId;fileTab=staff()?b.dataset.targetTab:'documents';current='cases';await render();});action('[data-read]',async b=>{await api('notifications/'+b.dataset.read+'/read','POST');await render();});}

async function account(){document.querySelector('#subtitle').textContent=user.must_change_password?'Choose a new password before accessing your documents.':'Keep your sign-in details up to date.';content.innerHTML=card(user.must_change_password?'Set your own password':'Change your password',form('password-form',input(user.must_change_password?'Temporary password from your email':'Current password','currentPassword','password','','required autocomplete="current-password"')+input('New password','password','password','','required minlength="12" maxlength="128" autocomplete="new-password"'),'Save new password'));bindForm('password-form',async v=>{await api('auth/password','POST',v);signedIn(null);history.replaceState({},'','/login');content.innerHTML='';success('Password saved. Sign in with your new password.');});}
async function categories(){const cats=await api('categories'),chosen=cats.find(c=>String(c.id)===String(selectedCategory)) || cats[0];if(chosen)selectedCategory=chosen.id;document.querySelector('#header-actions').innerHTML=manager()?'<button class="primary" id="new-category">＋ Add category</button>':'';content.innerHTML=`<div class="category-workspace"><section class="category-list"><h2>Services</h2>${cats.map(c=>`<button data-category="${c.id}" class="${c.id===chosen?.id?'selected':''}"><span>${c.parent_id?'↳':'▦'} ${esc(c.name)}<small>${c.fields.length} fields · ${c.status==='PUBLISHED'?'Published':'Draft'}</small></span></button>`).join('')||'<p>No categories yet.</p>'}</section><section class="card category-detail">${chosen?`<div class="section-heading"><div><h2>${esc(chosen.name)}</h2><p>${chosen.parent_id?'Subcategory of '+esc(cats.find(c=>c.id===chosen.parent_id)?.name):'Parent category'} · Version ${chosen.version}</p></div>${manager()?'<div class="row-actions"><button class="primary" id="add-field">＋ Add field</button>'+badge(chosen.status)+'</div>':badge(chosen.status)}</div><p class="muted">These are the fields and documents clients see when this category is assigned.</p>${chosen.status==='DRAFT'?'<p class="notice">Draft changes are not visible to clients. Publish this category when ready. Existing files keep their assigned checklist; Operations can apply the published checklist from the file’s More actions menu.</p>':''}<div class="table-wrap"><table><thead><tr><th>Field / document</th><th>Type</th><th>Required</th><th></th></tr></thead><tbody>${chosen.fields.map((f,i)=>`<tr><td><strong>${esc(f.label)}</strong><small>${esc(guideSummary(f.guide))}</small></td><td>${esc(f.type==='file'?'Document upload':f.type)}</td><td>${f.required?'Yes':'Optional'}</td><td>${manager()?`<div class="category-field-actions"><button data-field-up="${i}" aria-label="Move ${esc(f.label)} up" ${i===0?'disabled':''}>↑</button><button data-field-down="${i}" aria-label="Move ${esc(f.label)} down" ${i===chosen.fields.length-1?'disabled':''}>↓</button><button data-field-design="${i}">Design</button><button data-edit-field="${i}">Edit</button><button class="danger-button field-delete" data-remove-field="${i}" aria-label="Remove ${esc(f.label)}">Delete</button></div>`:''}</td></tr>`).join('')}</tbody></table></div>${!chosen.fields.length?empty('Build this category’s checklist','Add the information fields and documents your clients need to provide.'):''}<div class="form-actions">${manager()?`<button class="primary" id="category-stage">${chosen.status==='DRAFT'?'Publish category':'Create new draft'}</button>`:''}${manager()?'<button id="category-instructions">Client instructions</button><button id="edit-category">Edit category</button><button id="delete-category" class="danger-button">Delete category</button>':''}<button id="preview-category">Preview client checklist</button></div>`:empty('Start with a service category','Create a category, add its fields, then publish it.')}</section></div>`;action('[data-category]',async b=>{selectedCategory=b.dataset.category;await render();});action('#new-category',async()=>{modal('Add a category',form('category-create',input('Category name','name','text','','required')+select('Parent category','parentId',[['','None — parent category'],...cats.map(c=>[c.id,c.name])]),'Create category'));bindForm('category-create',async v=>{const r=await api('categories','POST',{name:v.name,parentId:v.parentId?Number(v.parentId):null});selectedCategory=r.id;closeModal();await render();});});if(!chosen)return;action('#edit-category',async()=>{modal('Edit category',form('category-edit',input('Category name','name','text',chosen.name,'required maxlength="200"')+select('Parent category','parentId',[['','None — parent category'],...cats.filter(c=>c.id!==chosen.id).map(c=>[c.id,c.name])],chosen.parent_id || '')+'<p class="hint">Name and parent can be updated here. To change a published checklist, create a new draft; existing client files keep their current requirements.</p>','Save category'));bindForm('category-edit',async v=>{await api('categories/'+chosen.id,'PATCH',{name:v.name,parentId:v.parentId?Number(v.parentId):null});closeModal();await render();success('Category updated.');});});action('#delete-category',async()=>{modal('Delete category',`<p>Delete <strong>${esc(chosen.name)}</strong> and its unused template versions? This cannot be undone. Categories assigned to files or containing subcategories cannot be deleted.</p>`+form('category-delete',check('I confirm deleting this category','confirm',false),'Delete category'));bindForm('category-delete',async(v,f)=>{if(!f.elements.confirm.checked)throw new Error('Confirm deletion first.');await api('categories/'+chosen.id,'DELETE',{confirm:true});selectedCategory=null;closeModal();await render();success('Category deleted.');});});action('#category-stage',async()=>{await api(`categories/${chosen.id}/${chosen.status==='DRAFT'?'publish':'draft'}`,'POST');await render();success(chosen.status==='DRAFT'?'Category published. It is ready to assign.':'New draft created. Existing client files keep their current checklist.');});action('#preview-category',async()=>modal('What the client will see',categoryGuidance(chosen.fields)+categoryLayout(chosen.fields.filter(f=>!f.instructionRole),{},true)));bindFieldDesign(chosen);bindCategoryInstructions(chosen);action('[data-remove-field]',async b=>{const fields=chosen.fields.filter((f,i)=>i!==Number(b.dataset.removeField));await saveCategoryFields(chosen,fields);await render();});
 const edit=(index)=>{if(index!=null){const existing=chosen.fields[index];modal('Edit field text',form('field-text',input('Field label','label','text',existing.label,'required maxlength="200"')+guideEditor('Description / instructions','guide',existing.guide)+'<p class="hint">Type is fixed: '+esc(existing.type)+'. Existing files retain their current checklist. Published templates become a new draft.</p>','Save field text'));bindGuideEditors();bindForm('field-text',async v=>{const fields=chosen.fields.map((f,i)=>i===index?{...f,label:v.label,guide:v.guide}:f);await saveCategoryFields(chosen,fields);closeModal();await render();success('Field text saved. Publish the draft when ready.');});return;}const f=index==null?{label:'',type:'file',guide:'',required:true}:chosen.fields[index];modal(index==null?'Add a field or document':'Edit requirement',(chosen.status==='PUBLISHED'?'<p class="hint">Saving creates a new draft. Publish it to use this field on newly initiated files; existing client checklists stay unchanged.</p>':'')+form('field-edit',input('Field / document name','label','text',f.label,'required')+select('Type','type',[['file','Document upload'],['text','Short text'],['textarea','Long answer'],['email','Email'],['date','Date'],['number','Number'],['dropdown','Dropdown'],['checkbox','Checkbox'],['phone','Phone number'],['url','Website URL'],['radio','Single-choice buttons'],['heading','Section heading'],['paragraph','Instructions / paragraph'],['divider','Divider']],f.type)+guideEditor('Instructions for the client','guide',f.guide)+check('Required to complete the file','required',f.required)+`<div id="dropdown-options">${area('Dropdown options — one per line','options',(f.options || []).join('\n'))}</div><details><summary>More options</summary>${check('Repeat for each applicant','applicantSpecific',f.applicantSpecific)+input('Number of document uploads','fileCount','number',f.fileCount || 1,'min="1" max="10"')+input('Maximum file size (MB)','maxMB','number',f.maxMB || 10,'min="1" max="10"')+input('Allowed formats (pdf,jpg,png)','formats','text',(f.formats || ['pdf','jpg','png']).join(','))+input('Example link (HTTPS)','sampleUrl','url',f.sampleUrl || '')+input('Minimum value','min','number',f.min ?? '')+input('Maximum value','max','number',f.max ?? '')+check('Date must be today or later','futureOnly',f.futureOnly)+select('Show only when this field matches','conditionKey',[['','Always show'],...chosen.fields.filter(other=>other.key!==f.key&&!['file','heading','paragraph','divider'].includes(other.type)).map(other=>[other.key,other.label])],f.condition?.key || '')+input('Matching answer','conditionEquals','text',f.condition?JSON.stringify(f.condition.equals):'')}</details>`,'Save requirement'));bindGuideEditors();const type=document.querySelector('#field-edit [name=type]');const toggle=()=>document.querySelector('#dropdown-options').hidden=!['dropdown','radio'].includes(type.value);type.onchange=toggle;toggle();bindForm('field-edit',async(v,form)=>{let equals=v.conditionEquals;try{equals=JSON.parse(equals);}catch{}const field={key:f.key || crypto.randomUUID(),label:v.label,type:v.type,guide:v.guide,required:['heading','paragraph','divider'].includes(v.type)?false:form.elements.required.checked,options:v.options.split('\n').map(v=>v.trim()).filter(Boolean),applicantSpecific:form.elements.applicantSpecific.checked,fileCount:Number(v.fileCount),maxMB:Number(v.maxMB),formats:v.formats.split(',').map(v=>v.trim()),sampleUrl:v.sampleUrl,futureOnly:form.elements.futureOnly.checked,min:v.min===''?undefined:Number(v.min),max:v.max===''?undefined:Number(v.max),condition:v.conditionKey?{key:v.conditionKey,equals}:undefined};const fields=[...chosen.fields];if(index==null)fields.push(field);else fields[index]=field;await saveCategoryFields(chosen,fields);closeModal();await render();success('Requirement saved. Publish the draft when ready.');});};action('#add-field',async()=>edit(null));action('[data-edit-field]',async b=>edit(Number(b.dataset.editField)));
}
async function restoreSession(){document.body.classList.add('session-pending');document.querySelector('#session-loading').hidden=false;document.querySelector('#retry-session').hidden=true;document.querySelector('#session-loading-message').textContent='Checking your session.';try{const value=await api('auth/me');signedIn(value);restoreWorkspaceUrl();await render(true);}catch(error){if(error.status===401){signedIn(null);return;}document.querySelector('#session-loading-message').textContent='Unable to check your session. Check your connection and try again.';document.querySelector('#retry-session').hidden=false;}}
document.querySelector('#retry-session').onclick=restoreSession;
restoreSession();

setInterval(()=>{if(user&&staff()&&!user.must_change_password&&!document.hidden&&!document.querySelector('#dialog').open&&['intake','overview'].includes(current))render().catch(report);},30000);
function renderClientOverview(data,pane){const {file,progress}=data;pane.innerHTML=card('Client profile',`<div class="client-profile-grid">${[['Client name',file.client_name],['Portal email',file.client_email],['Client notifications',file.client_notifications_enabled===0?'Stopped':'Enabled'],['Service category',file.category_name],['File owner',file.owner_name || 'Unassigned'],['File stage',label(file.status)],['Operational status',file.operational_status_name || 'Not set'],['Document reminders',file.reminder_every_hours?'Every '+file.reminder_every_hours+' hours':'Off'],['Collection deadline',file.due_at?date(file.due_at):'No deadline'],['Opened',date(file.created_at)],['Checklist',progress.satisfied+' / '+progress.total+' required items complete']].map(([k,v])=>`<div><small>${esc(k)}</small><strong>${k==='Operational status'?statusPill(v,file.operational_status_color):esc(v || 'Not supplied')}</strong></div>`).join('')}</div>`)+card(file.source_contract_id?.startsWith('manual:')?'Previous client record':'Contract Manager dossier',`<p class="muted">${file.source_contract_id?.startsWith('manual:')?'Client details recorded by Operations during manual onboarding.':'Review the client’s background, sales handover and source documents before progressing the file.'}</p>${summary(file.summary_json)}`);}
function renderConversationPanel(data,pane){destroyEmailComposer();if(conversationTab==='crm')conversationTab='conversation';syncWorkspaceUrl();pane.closest('.client-file-layout')?.classList.toggle('conversation-expanded',conversationExpanded);pane.innerHTML=`<div class="conversation-heading"><div><h2>Conversations</h2><small>All communication for this file</small></div><div class="conversation-controls"><button id="email-delivery-view">${conversationTab==='emails'?'Back to conversation':'Email delivery'}</button><button id="expand-conversation">${conversationExpanded?'Back to file':'Expand view'}</button><button id="refresh-chat" aria-label="Refresh conversation">↻</button></div></div><div class="tabs conversation-tabs"><button data-conversation="conversation" class="${conversationTab==='conversation'?'active':''}">Client conversation</button><button data-conversation="notes" class="${conversationTab==='notes'?'active':''}">Internal notes</button></div><div id="conversation-body"></div>`;action('#email-delivery-view',async()=>{conversationTab=conversationTab==='emails'?'conversation':'emails';renderConversationPanel(data,pane);});action('#expand-conversation',async()=>{conversationExpanded=!conversationExpanded;renderConversationPanel(data,pane);pane.scrollIntoView({behavior:'smooth',block:'start'});});action('#refresh-chat',async()=>{for(const key of crmConversationCache.keys())if(key.startsWith(user.id+':'+data.file.id+':'))crmConversationCache.delete(key);await render();});action('[data-conversation]',async b=>{conversationTab=b.dataset.conversation;await render();});const body=pane.querySelector('#conversation-body');if(conversationTab==='emails'){renderEmailHistory(data,body);}else if(conversationTab==='notes'){body.innerHTML='<p class="chat-channel">PRIVATE TEAM NOTES <span>Hidden from the client</span></p>'+messageThread(data.events.filter(e=>e.action==='INTERNAL_NOTE'))+form('workspace-note',area('Internal note','message'),'Save note');bindForm('workspace-note',async v=>{await api('cases/'+data.file.id+'/notes','POST',v);await render();success('Internal note saved.');});}else renderUnifiedConversation(data,body);}


function reminderControl(value=''){return select('Automatic document reminders','reminderEveryHours',[['','Off'],[1,'Every hour'],[6,'Every 6 hours'],[12,'Every 12 hours'],[24,'Every day'],[48,'Every 2 days'],[72,'Every 3 days'],[168,'Every week'],[336,'Every 2 weeks'],[720,'Every 30 days'],...(value&&![1,6,12,24,48,72,168,336,720].includes(Number(value))?[[value,'Every '+value+' hours']]:[])],value || '');}
async function fileStatuses(){const rows=await api('file-statuses');document.querySelector('#header-actions').innerHTML='<button id="add-status" class="primary">Add status</button>';content.innerHTML=card('Your operational statuses','<p class="muted">Use your own labels to organise files. These labels do not change document approval stages.</p>'+(rows.length?`<table><thead><tr><th>Status</th><th>Actions</th></tr></thead><tbody>${rows.map(s=>`<tr><td>${statusPill(s.name,s.color)}</td><td><button data-edit-status="${s.id}">Edit</button> <button data-delete-status="${s.id}">Delete</button></td></tr>`).join('')}</tbody></table>`:empty('Create your first status','Examples: Waiting for client, Under assessment, Ready for appointment.')));const edit=s=>{modal(s?'Edit status':'Create status',form('status-editor',input('Status name','name','text',s?.name || '','required maxlength="100"')+input('Status color','color','color',s?.color || '#137f75'),'Save status'));bindForm('status-editor',async v=>{await api(s?'file-statuses/'+s.id:'file-statuses',s?'PATCH':'POST',v);closeModal();await render();success('Status saved.');});};action('#add-status',async()=>edit(null));action('[data-edit-status]',async b=>edit(rows.find(s=>String(s.id)===b.dataset.editStatus)));action('[data-delete-status]',async b=>{if(!confirm('Delete this unused status? Statuses assigned to files cannot be deleted.'))return;await api('file-statuses/'+b.dataset.deleteStatus,'DELETE',{confirm:true});await render();success('Status deleted.');});}
async function renderFileTracking(data,pane){const {file}=data,statuses=await api('file-statuses');pane.innerHTML=card('Status & document reminders',form('file-preferences',select('Operational status','operationalStatusId',[['','Not set'],...statuses.map(s=>[s.id,s.name])],file.operational_status_id || '')+reminderControl(file.reminder_every_hours)+check('Stop client notifications','stopClientNotifications',file.client_notifications_enabled===0)+'<p class="hint">Stopped notifications suppress client emails, portal alerts and reminders for this file. Internal staff alerts remain enabled. Enable notifications before sending portal access. </p><p class="hint">Reminders start after the selected interval. Only required documents that are missing or rejected are included. Pending review and accepted uploads are excluded. Delivery uses your saved email provider; outgoing email must be enabled.</p>'+`<p class="hint">Next check: ${file.next_reminder_at?esc(connectionTime(file.next_reminder_at)):'Not scheduled'}</p>`,'Save file preferences'))+card('Expiry tracker',`<p class="muted">Track passport, visa, permit or other renewal dates. Alerts go to the client and file owner.</p><button id="add-expiry">Add expiry date</button>${data.expiries.length?`<div class="table-wrap"><table><thead><tr><th>Item</th><th>Expires</th><th>Reminder</th><th></th></tr></thead><tbody>${data.expiries.map(e=>`<tr><td><strong>${esc(e.label)}</strong></td><td>${date(e.expires_on)}</td><td>${e.remind_before_days} days before; every ${e.repeat_days} days<small>${e.last_notice_at?'Last alert '+esc(connectionTime(e.last_notice_at)):'No alerts yet'}</small></td><td><button data-remove-expiry="${e.id}">Remove</button></td></tr>`).join('')}</tbody></table></div>`:empty('No expiry dates tracked','Add an item and choose how early your client should be notified.')}`);bindForm('file-preferences',async(v,f)=>{await api('cases/'+file.id+'/preferences','PUT',{operationalStatusId:v.operationalStatusId?Number(v.operationalStatusId):null,reminderEveryHours:v.reminderEveryHours?Number(v.reminderEveryHours):null,clientNotificationsEnabled:!f.elements.stopClientNotifications.checked});await render();success('File preferences saved.');});action('#add-expiry',async()=>{modal('Track an expiry',form('expiry-editor',input('Item / document name','label','text','','required maxlength="160"')+input('Expiry date','expiresOn','date','','required')+input('Start alerts this many days before expiry','remindBeforeDays','number',30,'min="0" max="365" required')+input('Repeat alerts every (days)','repeatDays','number',7,'min="1" max="90" required')+'<p class="hint">Alerts repeat until expiry, followed by a final expiry notice. Closed files are excluded. Date thresholds follow the database server’s calendar.</p>','Save expiry'));bindForm('expiry-editor',async v=>{await api('cases/'+file.id+'/expiries','POST',{...v,remindBeforeDays:Number(v.remindBeforeDays),repeatDays:Number(v.repeatDays)});closeModal();await render();success('Expiry date saved.');});});action('[data-remove-expiry]',async b=>{if(!confirm('Stop tracking this expiry date?'))return;await api('cases/'+file.id+'/expiries/'+b.dataset.removeExpiry,'DELETE');await render();success('Expiry removed.');});}
function statusPill(name,color){const safe=/^#[a-f0-9]{6}$/i.test(color || '')?color:'#137f75';return `<span class="status-pill" style="background-color:${safe}14;border-color:${safe}66"><i style="background-color:${safe}"></i>${esc(name || 'Not set')}</span>`;}
async function saveCategoryFields(chosen,fields){if(chosen.status==='PUBLISHED')await api('categories/'+chosen.id+'/draft','POST');await api('categories/'+chosen.id+'/fields','PUT',{fields});}
function bindFieldDesign(chosen){for(const direction of ['up','down'])action('[data-field-'+direction+']',async b=>{const index=Number(direction==='up'?b.dataset.fieldUp:b.dataset.fieldDown),target=index+(direction==='up'?-1:1),fields=[...chosen.fields];if(target<0||target>=fields.length)return;[fields[index],fields[target]]=[fields[target],fields[index]];await saveCategoryFields(chosen,fields);await render();success('Field order saved. Publish the draft when ready.');});action('[data-field-design]',async b=>{const index=Number(b.dataset.fieldDesign),f=chosen.fields[index];modal('Field layout',form('field-layout',input('Section / group title','section','text',f.section || '','maxlength="160"')+select('Field width','width',[['full','Full width'],['half','Half width']],f.width || 'full'),'Save layout'));bindForm('field-layout',async v=>{const fields=chosen.fields.map((field,i)=>i===index?{...field,section:v.section,width:v.width}:field);await saveCategoryFields(chosen,fields);closeModal();await render();success('Layout saved. Publish the draft when ready.');});});}
function categoryLayout(fields,values={},disabled=false){let lastSection='';return `<div class="category-form-layout">${fields.map((f,i)=>{const name=String(f.controlName || f.key || i),v=values[name]??'',section=f.section&&f.section!==lastSection?`<h3 class="layout-section">${esc(f.section)}</h3>`:'';lastSection=f.section || '';if(f.type==='heading')return section+`<div class="layout-heading"><h3>${esc(f.label)}</h3><div class="formatted-guide">${guideMarkup(f.guide)}</div></div>`;if(f.type==='paragraph')return section+`<div class="layout-instructions"><strong>${esc(f.label)}</strong><div class="formatted-guide">${guideMarkup(f.guide)}</div></div>`;if(f.type==='divider')return section+'<hr class="layout-divider">';let control=f.type==='textarea'?area(f.label,name,v):f.type==='dropdown'?select(f.label,name,[['','Choose an option'],...f.options.map(o=>[o,o])],v):f.type==='checkbox'?check(f.label,name,v):f.type==='radio'?`<fieldset><legend>${esc(f.label)}</legend>${f.options.map(o=>`<label class="check"><input type="radio" name="${esc(name)}" value="${esc(o)}" ${String(v)===o?'checked':''}>${esc(o)}</label>`).join('')}</fieldset>`:f.type==='file'?`<div class="layout-file"><strong>${esc(f.label)}</strong><p>Upload ${esc((f.formats || []).join(', ').toUpperCase())} · ${f.maxMB || 10} MB maximum</p><button type="button" disabled>Choose document</button></div>`:input(f.label,name,f.type==='phone'?'tel':f.type,v);return section+`<div class="layout-field ${f.width==='half'?'half':'full'}">${control}<div class="formatted-guide">${guideMarkup(f.guide)}</div>${f.required?'<small class="hint">Required</small>':''}</div>`;}).join('')}</div>`;}
